<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot; use Throwable; use Pterodactyl\Models\Server; use Pterodactyl\Repositories\Wings\DaemonRepository; class ConsoleLog extends DaemonRepository { public function tail(Server $server, int $lines): ?array { $lines = max(1, min(100, $lines)); try { $response = $this->setServer($server)->getHttpClient()->get( sprintf('/api/servers/%s/logs?size=%d', $server->uuid, $lines), ['timeout' => 5, 'connect_timeout' => 3], ); } catch (Throwable) { return null; } $body = json_decode($response->getBody()->__toString(), true); $data = is_array($body) ? ($body['data'] ?? $body) : null; return is_array($data) ? array_slice(array_values(array_map('strval', $data)), -$lines) : null; } } 